import{_ as e,o as a,c as o,ag as s}from"./chunks/framework.DNmTgtHf.js";const m=JSON.parse('{"title":"ChatGPT Doc-Import Prompt","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/reference/ChatGptDocImportPrompt.md","filePath":"todo/study_plan/reference/ChatGptDocImportPrompt.md"}'),n={name:"todo/study_plan/reference/ChatGptDocImportPrompt.md"};function r(p,t,i,c,d,l){return a(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="chatgpt-doc-import-prompt" tabindex="-1">ChatGPT Doc-Import Prompt <a class="header-anchor" href="#chatgpt-doc-import-prompt" aria-label="Permalink to &quot;ChatGPT Doc-Import Prompt&quot;">​</a></h1><p>Paste this at the end of any ChatGPT study thread to get a raw, complete dump of the discussion. Bring the output back here via <code>temp.md</code> (repo root) — Claude does ALL the structuring, standards pass, splitting, and Notion formatting during import (routine in <code>CLAUDE.md</code> under &quot;ChatGPT doc-import workflow&quot;). ChatGPT&#39;s only job is complete, faithful capture.</p><blockquote><p>History: an earlier version of this prompt asked ChatGPT to structure the page (sections, Quick recall, format rules). Dropped deliberately — structuring happens at import time anyway, and source-side filtering (&quot;skip basics&quot;) risked silent content loss.</p></blockquote><hr><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dump this entire conversation as one Markdown document for my study notes. Don&#39;t worry about structure, section order, or polish — my own system will restructure and format it later. Your only job is COMPLETE and FAITHFUL capture:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Include EVERY topic, sub-question, example, and tangent we discussed in this thread. Nothing gets dropped or summarized away — if we spent time on it, it&#39;s in the dump.</span></span>
<span class="line"><span>- Most important: every point where I was confused, guessed wrong, or asked a follow-up — capture my misconception AND the correction explicitly, marked clearly (e.g. &quot;Misconception: ... / Correction: ...&quot;). These are the most valuable parts.</span></span>
<span class="line"><span>- Do NOT add material we didn&#39;t discuss (no padding for completeness, no surveys of alternatives, no historical trivia). Only what was actually covered in this chat.</span></span>
<span class="line"><span>- Group related points together so the dump is readable, but don&#39;t sweat the ordering beyond that.</span></span>
<span class="line"><span>- Plain Markdown, no HTML, no emojis.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Output everything as one Markdown code block so I can copy it cleanly.</span></span></code></pre></div>`,5)])])}const h=e(n,[["render",r]]);export{m as __pageData,h as default};
